from __future__ import annotations

import secrets
import string
from urllib.parse import urlparse

CODE_ALPHABET = string.ascii_letters + string.digits
CODE_LENGTH = 7
ALLOWED_SCHEMES = frozenset({"http", "https"})


class InvalidURLError(ValueError):
    """Raised when a URL cannot be shortened."""


class UnknownCodeError(KeyError):
    """Raised when a short code has no stored URL."""


def is_valid_url(url: str) -> bool:
    """Whether ``url`` is an absolute http(s) URL with a host."""
    if not isinstance(url, str) or not url.strip():
        return False
    parsed = urlparse(url.strip())
    if parsed.scheme not in ALLOWED_SCHEMES:
        return False
    return bool(parsed.netloc)


def generate_code(length: int = CODE_LENGTH) -> str:
    """Return a cryptographically random short code."""
    if length < 1:
        raise ValueError("length must be at least 1")
    return "".join(secrets.choice(CODE_ALPHABET) for _ in range(length))


class Shortener:
    """Stores URLs against generated short codes."""

    def __init__(self, code_length: int = CODE_LENGTH) -> None:
        self._code_length = code_length
        self._by_code: dict[str, str] = {}
        self._by_url: dict[str, str] = {}

    def shorten(self, url: str) -> str:
        """Return a short code for ``url``, reusing one if already stored."""
        if not is_valid_url(url):
            raise InvalidURLError(f"not a valid http(s) URL: {url!r}")
        normalised = url.strip()
        existing = self._by_url.get(normalised)
        if existing is not None:
            return existing
        code = generate_code(self._code_length)
        while code in self._by_code:
            code = generate_code(self._code_length)
        self._by_code[code] = normalised
        self._by_url[normalised] = code
        return code

    def resolve(self, code: str) -> str:
        """Return the URL stored for ``code``."""
        try:
            return self._by_code[code]
        except KeyError:
            raise UnknownCodeError(f"unknown short code: {code!r}") from None

    def count(self) -> int:
        """Number of distinct URLs stored."""
        return len(self._by_code)
